import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            total += a[i];
        }
        Arrays.sort(a);
        StringBuilder out = new StringBuilder();
        while (q-- > 0) {
            long need = nextLong(), backup = nextLong();
            // First capacity >= need; cost is non-increasing below it and non-decreasing above it.
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (a[mid] < need) lo = mid + 1; else hi = mid;
            }
            long answer = Long.MAX_VALUE;
            for (int i = lo - 1; i <= lo; i++) {
                if (i < 0 || i >= n) continue;
                long w = a[i];
                answer = Math.min(answer, Math.max(0, need - w) + Math.max(0, backup - (total - w)));
            }
            out.append(answer).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"sort"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, q := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	total := int64(0)
	for i := range a {
		a[i] = nextInt()
		total += a[i]
	}
	slices.Sort(a)
	var out []byte
	for ; q > 0; q-- {
		need, backup := nextInt(), nextInt()
		// First capacity >= need; cost is non-increasing below it and non-decreasing above it.
		p := sort.Search(n, func(i int) bool { return a[i] >= need })
		answer := int64(-1)
		for i := p - 1; i <= p; i++ {
			if i < 0 || i >= n {
				continue
			}
			w := a[i]
			cost := max(0, need-w) + max(0, backup-(total-w))
			if answer < 0 || cost < answer {
				answer = cost
			}
		}
		out = strconv.AppendInt(out, answer, 10)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
